  function proxiedImage(url){ return url ? `/api/image?url=${encodeURIComponent(url)}` : ''; }
  function resilientImageMarkup(url,alt='',attributes=''){
    const fallback='images/launch-placeholder.svg';
    if(!url)return `<img src="${fallback}" alt="${esc(alt)}" class="local-image-fallback" ${attributes}>`;
    return `<img src="${esc(proxiedImage(url))}" data-direct-src="${esc(url)}" data-fallback-src="${fallback}" data-image-stage="proxy" alt="${esc(alt)}" ${attributes}>`;
  }
  function wireImageFallbacks(root=document){
    $$('img[data-direct-src]',root).forEach(img=>{if(img.dataset.fallbackWired)return;img.dataset.fallbackWired='1';const recover=()=>{const stage=img.dataset.imageStage;if(stage==='proxy'){img.dataset.imageStage='direct';img.src=img.dataset.directSrc;return}if(stage==='direct'){img.dataset.imageStage='local';img.classList.add('local-image-fallback');img.src=img.dataset.fallbackSrc;return}img.onerror=null};img.addEventListener('error',recover);if(img.complete&&img.naturalWidth===0)recover()});
  }
  function toast(message, type='', detail='') {
    const el = document.createElement('div');
    el.className = `toast ${type}`;
    el.innerHTML = `<strong>${esc(message)}</strong>${detail ? `<small>${esc(detail)}</small>`:''}`;
    $('#toastStack').append(el);
    setTimeout(() => el.remove(), 4200);
  }
  async function api(url, options={}) {
    const response = await fetch(url, options);
    let data;
    try { data = await response.json(); } catch { data = {}; }
    if (!response.ok) {
      const error = new Error(data.error || data.detail || `HTTP ${response.status}`);
      error.code = data.code || 'request_failed';
      error.detail = data.detail || '';
      error.status = response.status;
      throw error;
    }
    return data;
  }
