    const related=K.filter(x=>x.domain===item.domain&&x.id!==item.id).sort((a,b)=>(a.level===item.level?-1:1)).slice(0,6);$('#relatedKnowledgeTopics').innerHTML=related.map(x=>`<button data-related-knowledge="${x.id}"><span>${esc(KL[x.level].fa)}</span><strong>${esc(x.title.fa)}</strong></button>`).join('');$$('[data-related-knowledge]').forEach(btn=>btn.addEventListener('click',()=>openKnowledgeArticle(btn.dataset.relatedKnowledge)));enhanceTerminology($('#knowledgeReaderMain'));
