  function agencyArticleKey(item){
    const value=String(item?.url||item?.id||'');let hash=2166136261;
    for(let i=0;i<value.length;i++){hash^=value.charCodeAt(i);hash=Math.imul(hash,16777619)}
    return `${String(item?.agency||'agency').toLowerCase()}-${(hash>>>0).toString(36)}`;
  }
  function agencyArticleHash(item){return `#agency-article/${agencyArticleKey(item)}/${encodeURIComponent(item.url||'')}`}
  function parseAgencyArticleHash(hash=location.hash.slice(1)){
    if(!hash.startsWith('agency-article/'))return null;const parts=hash.split('/'),key=parts[1]||'';let url='';
    try{url=decodeURIComponent(parts.slice(2).join('/'))}catch{}
    return {key,url};
  }
