    $('#agencyArticleContent').innerHTML=`<article class="agency-article-page"><section class="agency-article-hero"><div class="agency-article-image">${heroImage}<span class="agency-badge ${esc(agency)}">${esc(agency)}</span></div><div class="agency-article-intro"><div class="agency-article-meta"><span>${esc(detail?.category||item.category||'Official update')}</span><time>${fmtDate(detail?.published||item.published,true)}</time><span>${detail?agencyArticleReadingLabel(detail.reading_minutes):state.lang==='fa'?'در حال محاسبه…':'Calculating…'}</span></div><h1>${esc(title)}</h1><div class="agency-article-official-title">${esc(showOriginal?(titleFa||''):titleEn)}</div><label class="agency-original-toggle ${hasOriginal?'':'disabled'}"><input id="agencyOriginalToggle" type="checkbox" ${showOriginal?'checked':''} ${hasOriginal?'':'disabled'}><span>${agency==='NASA'?'نمایش متن انگلیسی':'نمایش متن رسمی انگلیسی'}</span></label><p class="agency-article-lead">${esc(summary)}</p>${warning?`<div class="agency-article-warning">${icon('i-info')}<span>${esc(warning)}</span></div>`:''}</div></section>${body}<section class="agency-article-source-note"><div>${icon('i-source')}<p><strong>${state.lang==='fa'?'منبع و مسئولیت متن':'Source and text responsibility'}</strong><span>${state.lang==='fa'?'متن انگلیسی متعلق به منبع رسمی است. ترجمه و خلاصه فارسی برای مطالعه سریع ارائه می‌شود.':'The official agency owns the English text. Persian translation and summary are provided for rapid study.'}</span></p></div><a href="${esc(official)}" target="_blank" rel="noreferrer">${state.lang==='fa'?`بازکردن مقاله کامل در ${esc(agency)}`:`Open full article on ${esc(agency)}`} ${icon('i-external')}</a></section></article>`;
