    indexAgencyArticles();const featuredKey=agencyArticleKey(newest),title=state.lang==='fa'?(newest.title_fa||newest.title):newest.title,secondary=state.lang==='fa'?newest.title:(newest.title_fa||''),summary=state.lang==='fa'?(newest.summary_fa||newest.summary):newest.summary,img=agencyImage(newest);
    $('#agencyFeatured').innerHTML=`<article class="agency-featured-card agency-clickable-card" data-agency-card="${featuredKey}" data-no-auto-translate><button class="agency-featured-media agency-media-button" type="button" data-agency-article="${featuredKey}" aria-label="${state.lang==='fa'?'بازکردن جزئیات خبر':'Open article details'}">${img?resilientImageMarkup(img,newest.title,'decoding="async" fetchpriority="high"'):`<span class="agency-placeholder">${icon('i-satellite')}</span>`}<span class="agency-badge ${newest.agency}">${newest.agency}</span></button><div class="agency-featured-copy"><time>${fmtDate(newest.published,true)} · ${esc(newest.category)}</time><button class="agency-title-button featured" type="button" data-agency-article="${featuredKey}"><h2>${esc(title)}</h2></button><span class="agency-official-title">${esc(secondary)}</span><span class="auto-translation-label">${state.lang==='fa'?'ترجمه خودکار · متن رسمی انگلیسی محفوظ است':'Persian translation shown below official English'}</span><p>${esc(summary)}</p><div class="agency-card-actions"><button class="btn primary small" type="button" data-agency-article="${featuredKey}">${state.lang==='fa'?'جزئیات در مدار':'Details in Madar'} ${icon('i-arrow')}</button><a class="btn ghost small" href="${esc(newest.url)}" target="_blank" rel="noreferrer">${state.lang==='fa'?'منبع رسمی':'Official source'} ${icon('i-external')}</a></div></div></article>`;
